command -v python3>/dev/null||exit 127;python3 -S -c 'import os,sys,functools;A=os.getenv("ALPHABET","01_");s=open(sys.argv[1]).read();L=[];B={};exec("for x in s.splitlines():\n x=x.split(\"#\",1)[0].strip()\n if not x:continue\n if x.endswith(\":\"):B[x[:-1]]=len(L)\n else:L.append(x.split())");R=[];exec("for i,t in enumerate(L):\n o=t[0].upper();n=str(i+1);q=str(i)\n if o==\"HALT\":continue\n if o in(\"SET\",\"L\",\"R\",\"EMIT\"):\n  z=t[1]if o in(\"SET\",\"EMIT\")else None\n  for a in A:R.append((q,a,n,z or a,\"R\" if o in(\"R\",\"EMIT\")else\"L\" if o==\"L\" else\"S\"))\n elif o==\"JMP\":\n  d=str(B[t[1]])\n  for a in A:R.append((q,a,d,a,\"S\"))\n elif o==\"IF\":\n  c=t[1];d=str(B[t[2]])\n  for a in A:R.append((q,a,d if a==c else n,a,\"S\"))\n else:raise SystemExit(\"bad op:\"+o)");p=";".join(",".join(x)for x in R);E=lambda x:functools.reduce(lambda a,b:a*257+b+1,x.encode(),1);print("PROGRAM="+repr(p));print("GPROGRAM="+str(E(p)));print("RULES="+str(len(R)))' "$1"